CREATE TABLE listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seller_id uuid NOT NULL REFERENCES profiles(id), business_id uuid REFERENCES businesses(id), category_id uuid NOT NULL REFERENCES categories(id), location_id uuid REFERENCES locations(id), source_language varchar(10) NOT NULL REFERENCES languages(code), title varchar(160) NOT NULL, description text NOT NULL, listing_type varchar(30) NOT NULL DEFAULT 'product', transaction_type varchar(30) NOT NULL DEFAULT 'sell', price_type varchar(30) NOT NULL DEFAULT 'fixed', price_minor bigint CHECK(price_minor>=0), currency_code char(3) NOT NULL DEFAULT 'EUR', condition_code varchar(30), quantity integer NOT NULL DEFAULT 1 CHECK(quantity>=0), delivery_available boolean NOT NULL DEFAULT false, pickup_available boolean NOT NULL DEFAULT true, offers_allowed boolean NOT NULL DEFAULT true, status varchar(30) NOT NULL DEFAULT 'draft', moderation_status varchar(30) NOT NULL DEFAULT 'pending', view_count bigint NOT NULL DEFAULT 0, favorite_count bigint NOT NULL DEFAULT 0, published_at timestamptz, expires_at timestamptz, deleted_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE listing_translations(listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE, language_code varchar(10) NOT NULL REFERENCES languages(code), title varchar(160) NOT NULL, description text NOT NULL, slug varchar(200) NOT NULL, translation_status varchar(20) NOT NULL DEFAULT 'draft', translated_by varchar(30), PRIMARY KEY(listing_id,language_code), UNIQUE(language_code,slug));
CREATE TABLE listing_attribute_values(listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE, attribute_id uuid NOT NULL REFERENCES attributes(id), value_text text, value_number numeric, value_boolean boolean, value_date date, value_datetime timestamptz, value_option_id uuid REFERENCES attribute_options(id), value_json jsonb, PRIMARY KEY(listing_id,attribute_id), CHECK(num_nonnulls(value_text,value_number,value_boolean,value_date,value_datetime,value_option_id,value_json)=1));
CREATE TABLE listing_attribute_multi_options(listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE, attribute_id uuid NOT NULL REFERENCES attributes(id), option_id uuid NOT NULL REFERENCES attribute_options(id), PRIMARY KEY(listing_id,attribute_id,option_id));
CREATE TABLE listing_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE, storage_key text NOT NULL, media_type varchar(20) NOT NULL DEFAULT 'image', mime_type varchar(100), file_size_bytes bigint, sort_order integer NOT NULL DEFAULT 0, alt_text jsonb NOT NULL DEFAULT '{}', moderation_status varchar(30) NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE favorites(profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, listing_id uuid REFERENCES listings(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(profile_id,listing_id));
CREATE TABLE saved_searches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES profiles(id), name varchar(150), query_text varchar(255), category_id uuid REFERENCES categories(id), filters jsonb NOT NULL DEFAULT '{}', language_code varchar(10) REFERENCES languages(code), notification_frequency varchar(30) DEFAULT 'instant', is_active boolean NOT NULL DEFAULT true);
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id), buyer_id uuid NOT NULL REFERENCES profiles(id), amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency_code char(3) NOT NULL DEFAULT 'EUR', status varchar(30) NOT NULL DEFAULT 'pending', message text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid REFERENCES listings(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_participants(conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, last_read_at timestamptz, PRIMARY KEY(conversation_id,profile_id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES profiles(id), content text, attachment_key text, moderation_status varchar(30) NOT NULL DEFAULT 'approved', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id), buyer_id uuid NOT NULL REFERENCES profiles(id), seller_id uuid NOT NULL REFERENCES profiles(id), quantity integer NOT NULL DEFAULT 1, subtotal_minor bigint NOT NULL, shipping_minor bigint NOT NULL DEFAULT 0, platform_fee_minor bigint NOT NULL DEFAULT 0, total_minor bigint NOT NULL, currency_code char(3) NOT NULL DEFAULT 'EUR', status varchar(30) NOT NULL DEFAULT 'pending_payment', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), provider varchar(50) NOT NULL, provider_payment_id varchar(255) UNIQUE, amount_minor bigint NOT NULL, currency_code char(3) NOT NULL DEFAULT 'EUR', status varchar(30) NOT NULL, payment_method varchar(50), paid_at timestamptz, refunded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), carrier varchar(50), tracking_number varchar(150), label_storage_key text, status varchar(30) NOT NULL DEFAULT 'pending', shipped_at timestamptz, delivered_at timestamptz);
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid REFERENCES profiles(id), reported_listing_id uuid REFERENCES listings(id), reported_profile_id uuid REFERENCES profiles(id), reported_message_id uuid REFERENCES messages(id), reason_code varchar(50) NOT NULL, description text, status varchar(30) NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(reported_listing_id,reported_profile_id,reported_message_id)=1));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES profiles(id), notification_type varchar(50) NOT NULL, title varchar(200) NOT NULL, body text, payload jsonb NOT NULL DEFAULT '{}', channel varchar(30) NOT NULL DEFAULT 'in_app', read_at timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY, actor_id uuid REFERENCES profiles(id), action varchar(100) NOT NULL, entity_type varchar(50) NOT NULL, entity_id uuid, previous_values jsonb, new_values jsonb, ip_address inet, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(id,created_at)) PARTITION BY RANGE(created_at);
CREATE TABLE audit_logs_default PARTITION OF audit_logs DEFAULT;
